package com.primehr.evidence.application;
import com.primehr.evidence.domain.EvidenceArtifact.SourceType;import com.primehr.learningdevelopment.evaluation.application.LdEvaluationService;import com.primehr.performancemanagement.report.application.PerformanceReportingData.OutcomeQuery;import com.primehr.performancemanagement.report.application.PerformanceReportingService;import com.primehr.assessment.application.AssessmentValidationService;import com.primehr.security.*;import com.primehr.integration.administrative.PermissionDataScope;import com.primehr.shared.exception.*;import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.stereotype.Component;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.Instant;import java.util.HexFormat;
@Component public class PrimeHrEvidenceLiveSourceVerifier implements EvidenceLiveSourceVerifier{
 private final AssessmentValidationService competency;private final PerformanceReportingService performance;private final LdEvaluationService learning;private final AssessmentPermissionGuard competencyPermission;private final PerformanceReportingPermissionGuard performancePermission;private final LdEvaluationPermissionGuard learningPermission;private final ObjectMapper json;
 public PrimeHrEvidenceLiveSourceVerifier(AssessmentValidationService c,PerformanceReportingService p,LdEvaluationService l,AssessmentPermissionGuard cp,PerformanceReportingPermissionGuard pp,LdEvaluationPermissionGuard lp,ObjectMapper j){competency=c;performance=p;learning=l;competencyPermission=cp;performancePermission=pp;learningPermission=lp;json=j;}
 public Snapshot verify(String agency,Request r,String token,String actor,String correlation){if(r==null||r.type()==null||r.sourceId()==null||r.sourceId().isBlank()||r.sourceFingerprint()==null||r.sourceFingerprint().isBlank())throw new IllegalArgumentException("Complete exact source identity is required");return switch(r.type()){case COMPETENCY_PROFILE->competency(agency,r,token,actor);case PERFORMANCE_OUTCOME->performance(agency,r,token,actor,correlation);case LD_COMPLETION->learning(agency,r,token,actor,correlation);};}
 private Snapshot competency(String a,Request r,String token,String actor){competencyPermission.requireAgencyWide(AssessmentPermissionGuard.PERSON_PROFILE,PrimeHrAction.ACCESS,token);var p=competency.version(a,r.sourceId(),actor,PermissionDataScope.AGENCY_WIDE);String fp=sha(p);if(p.profileVersion()!=r.sourceVersion()||!fp.equals(r.sourceFingerprint()))throw new OptimisticConflictException("Competency profile source changed; reload the exact source");return new Snapshot(r.type(),p.id(),p.profileVersion(),fp,"Competency profile v"+p.profileVersion(),p.validatedAt());}
 private Snapshot performance(String a,Request r,String token,String actor,String c){performancePermission.require(PerformanceReportingPermissionGuard.OUTCOME_FEED,token);Instant changed=changed(r);var o=performance.outcomes(a,new OutcomeQuery(changed.minusSeconds(1),changed.plusSeconds(1),0,500),actor,c).content().stream().filter(x->x.outcomeId().equals(r.sourceId())).findFirst().orElseThrow(()->new ResourceNotFoundException("Exact performance outcome source not found"));if(o.recordVersion()!=r.sourceVersion()||!o.outcomeFingerprint().equals(r.sourceFingerprint())||!o.changedAt().equals(changed))throw new OptimisticConflictException("Performance outcome changed; reload the exact source");return new Snapshot(r.type(),o.outcomeId(),o.recordVersion(),o.outcomeFingerprint(),"Final performance outcome "+o.ratingLabel(),o.changedAt());}
 private Snapshot learning(String a,Request r,String token,String actor,String c){learningPermission.require(LdEvaluationPermissionGuard.COMPLETION_FEED,PrimeHrAction.ACCESS,token);Instant changed=changed(r);var o=learning.completionFeed(a,changed.minusSeconds(1),changed.plusSeconds(1),0,500,actor,c).content().stream().filter(x->x.completionId().equals(r.sourceId())).findFirst().orElseThrow(()->new ResourceNotFoundException("Exact L&D completion source not found"));if(o.recordVersion()!=r.sourceVersion()||!o.outcomeFingerprint().equals(r.sourceFingerprint())||!o.changedAt().equals(changed))throw new OptimisticConflictException("L&D completion changed; reload the exact source");return new Snapshot(r.type(),o.completionId(),o.recordVersion(),o.outcomeFingerprint(),"L&D completion - "+o.offeringTitle(),o.changedAt());}
 private static Instant changed(Request r){if(r.sourceChangedAt()==null)throw new IllegalArgumentException("sourceChangedAt is required");return r.sourceChangedAt();}private String sha(Object value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(json.writeValueAsString(value).getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException("Source fingerprint could not be calculated",e);}}
}
